"""SkyWynn Skill Trees 3 - THE ONE DATA TABLE for all 19 trees (8 class trees, 11 skill trees). Owner: Skyy (they/them).

R0 of research/Skill-Trees-3-Spec.md section 7: sections 3 + 4 of that spec transcribed (2026-10-20) with Skyy's answers (end of the spec,
docs/answered/skills.md 2026-10-18) applied:
  (a) a row opens on the TOTAL points spent anywhere in that tree (BL3 style): rows open at 0 / 5 / 10 / 15 / 20 / 25 (light trees 0 / 5 / 10 / 15)
  (b) 1 point per level - class trees: the class skill level, skill trees: that skill's level; no other source (no Tokens, no Dust)
  (c) the capstone (last row) costs 1 point (rank 1) and needs 25 total points in the tree (light trees: 15)
  (d) respec (built in SkyyTrees): coins 100 x level x min(n, 5) per tree per run + 1 free respec per tree per rebirth
  (e) light skills Fishing / Exploration / Acrobatics / Smithing = 2 branches x 4 rows
  (f) every rank of every upgrade costs 1 point; the row's free ability / perk is the only free thing
Build scripts IMPORT this file (SkyyTrees 0.4.0+ = the one writer of the tree pages; edit numbers HERE, then rebuild). Numbers are the spec's
first-pass placeholders - the balance pass (research/Balance-Pass-Spec.md) tunes them here.

Shape: TREES = [tree], tree = {name, kind "class" | "skill", light, branches: [{name, theme, rows: [row]}]},
row = {r, gate (total tree points the row needs), cap (True = capstone row), free (None | {name, text, hook}), ups: [up]},
up = {id (saved id, unique in its branch: r<row><a|b|c>, the capstone r<row>), name, max (ranks), cost (points a rank), text, hook}.
Saved key of an upgrade (SkyyTrees players/<pkey>.properties, v=3): <Class|Skill>.<Tree>.b<branch>.<id>=<rank>.

HOOKS (what makes an upgrade do something today; None = "(coming soon)": shown, never buyable, costs nothing - round R3 wires them):
  ("mod", <SkyyClasses ability id>, <modifier id>)  class upgrade = that modifier on that ability: rank 1 unlocks it for the ability's
                                                    modifier slots, each rank adds one modifier level (SkyyClasses 0.1.42 reads the ranks)
  ("abil", <line A1 | A2 | A3 | A4a | A4b>, <ability id>)  a class row's free ability (SkyyClasses ability lines; A4a / A4b = the A1-alts)
  ("old", "<OldTree>.<OldId>", <levels per rank>)   skill upgrade (or a free perk: levels while the row is open) = the SkyyTrees 0.3 node of
                                                    that key at (rank x levels per rank) levels - every reader of that node id (SkyySkills,
                                                    SkyyGear, SkyySacks, SkyyFishing, SkyyCooking, SkyyExploration, tree:fn:bonus / level)
                                                    keeps working unchanged; the sum over a tree never passes the old node's max (asserted)
  ("fx", ((<code>, <per rank>), ...))               R3a (2026-10-20): a CLASS upgrade wired by its effect codes (CLASS_FX below, applied
                                                    at import): SkyyTrees sends "f.<code>=<rank x per rank, summed over the tree>" in
                                                    tree:fn:abil and answers tree:fn:bonus "Class.fx.<code>"; FX_OWNER names the mod that
                                                    applies each code (it lists "Class.fx.<code>" in tree:reads:<mod>; SkyyTrees' own codes
                                                    are always live). A row's free "fx" hook = ("fx", <code>) (the Assassin's Shadow Clone).
MAPPING DECISIONS (generator notes, 2026-10-20; Skyy may change any of them):
  - Warrior: the spec's Bulwark Stance / Unbreakable are SkyyClasses' A1-alt A / B = Challenge / Guardian's Oath (research/classes/Warrior.md
    lists Bulwark Stance / Unbreakable as the A1-alts; SkyyClasses ships them as Challenge / Guardian's Oath) - texts show the real names.
  - Monk: the spec names 4 abilities; Cyclone Kick (SkyyClasses A3, the Palm Strike alt) comes free with Fist row 5 (the pattern's "row 5
    of one branch = the fifth ability").
  - Assassin: Shadow Clone (Executioner row 2) was parked in SkyyClasses; R3a makes it the row's free PASSIVE ability (no new rune):
    Cloak and Vanishing Act leave a Shadow Clone (fx code ShadowClone, SkyyClasses 0.1.43).
  - A class upgrade named like a modifier hooks the first ability its text names that HAS that modifier (SkyyClasses AB_MODS), else the
    row's / branch's own ability; anything else waits for R3.
  - Skill hooks keep Skyy's locked rules alive: Mining Fortune = tool + a tree node (Rich Seams), Smelting Fortune only in the Smithing tree
    (Thrift), Vein Burst / Tree Feller come with the row-2 perks (Vein Burst / Timber!) and grow with Wide Burst / Giant Reach.
"""

