CLASS_FREE_FX = {"Assassin.b2.r2": ("ShadowClone", "Cloak / Vanishing Act leave a clone: nearby enemies lose you; then it hits one (60%)")}


def fx_codes(u):
    """the (code, per rank) pairs of an upgrade with an fx hook ([] otherwise)"""
    h = u.get("hook")
    return list(h[1]) if h and h[0] == "fx" else []


def fx_owner(code):
    return FX_OWNER.get(code, "SkyyClasses")


def _fx_apply():
    """R3a: puts the fx hooks + texts of CLASS_FX into TREES (only upgrades that had no hook)"""
    seen = set()
    for t in TREES:
        if t["kind"] != "class":
            continue
        for bn, b in enumerate(t["branches"]):
            for r in b["rows"]:
                fk = "%s.b%d.r%d" % (t["name"], bn + 1, r["r"])
                if fk in CLASS_FREE_FX:
                    assert r["free"] is not None and r["free"]["hook"] is None, fk
                    r["free"]["hook"] = ("fx", CLASS_FREE_FX[fk][0])
                    r["free"]["text"] = CLASS_FREE_FX[fk][1]
                    seen.add(fk)
                for u in r["ups"]:
                    k = "%s.b%d.%s" % (t["name"], bn + 1, u["id"])
                    if k not in CLASS_FX:
                        continue
                    assert u["hook"] is None, ("CLASS_FX only wires coming-soon upgrades", k)
                    codes, nt, now = CLASS_FX[k]
                    u["hook"] = ("fx", tuple((c, float(v)) for c, v in codes))
                    if nt:
                        u["text"] = nt
                    u["now"] = now
                    seen.add(k)
    assert seen == set(CLASS_FX) | set(CLASS_FREE_FX), sorted(set(CLASS_FX) | set(CLASS_FREE_FX) - seen)


_fx_apply()

# ===================================================================================================================================
# Balance P4 T7 (research/Balance-P4-Combat-Spec.md Part 4; 2026-10-21): one modifier of one ability gets at most 5 levels from the class
# tree (mods.steps = Lv 2-5; SkyyClasses 0.1.44 also clamps all sources at 5 + the rebirth extra). The tree had up to 12 ranks on one
# (ability, modifier) - e.g. Arcane Breach Power 5 + 5. The extra ranks moved to the row's other upgrade (up to its own 5-rank and
# 5-per-modifier limits; the rest dropped). Saved ranks above a new max are clamped by SkyyTrees on read (TreeStore: num(.., 0, UMAX)),
# the freed points are unspent again. key -> (old max, new max); computed once by the generator in tools/dev/scratch/balp4b (deleted).
T7_MAX = {"Warrior.b3.r3a": (3, 2), "Warrior.b3.r3b": (3, 4),
          "Berserker.b1.r2a": (5, 4), "Berserker.b1.r2b": (3, 4), "Berserker.b1.r4a": (5, 4), "Berserker.b1.r4b": (4, 5),
          "Berserker.b1.r5a": (2, 4), "Berserker.b1.r5b": (3, 1), "Berserker.b2.r1a": (5, 1), "Berserker.b2.r1b": (4, 5),
          "Berserker.b2.r5a": (3, 4), "Berserker.b2.r5b": (3, 2),
          "Spellblade.b1.r1a": (5, 4), "Spellblade.b1.r1b": (4, 5), "Spellblade.b2.r1a": (5, 1), "Spellblade.b2.r1b": (3, 5),
          "Spellblade.b3.r2b": (3, 1), "Spellblade.b3.r5a": (3, 5), "Spellblade.b3.r5b": (3, 1),
          "Monk.b2.r1a": (5, 3), "Monk.b2.r1b": (4, 5), "Monk.b2.r2b": (3, 1), "Monk.b2.r4a": (4, 5), "Monk.b2.r4b": (4, 1),
          "Monk.b3.r2a": (5, 4), "Monk.b3.r2b": (3, 4), "Monk.b3.r4a": (3, 5), "Monk.b3.r4b": (3, 1)}
MOD_CAP = 5


def _t7_apply():
    seen = set()
    for t in TREES:
        if t["kind"] != "class":
            continue
        for bn, b in enumerate(t["branches"]):
            for r in b["rows"]:
                for u in r["ups"]:
                    k = "%s.b%d.%s" % (t["name"], bn + 1, u["id"])
                    if k in T7_MAX:
                        assert u["max"] == T7_MAX[k][0], ("T7: the old max moved", k, u["max"])
                        u["max"] = T7_MAX[k][1]
                        seen.add(k)
    assert seen == set(T7_MAX), sorted(set(T7_MAX) - seen)


def mod_ranks():
    """{(ability, modifier): the most class-tree ranks one player can hold on it} (Balance P4 T7: each <= MOD_CAP)"""
    out = {}
    for t in TREES:
        for b in t["branches"]:
            for r in b["rows"]:
                for u in r["ups"]:
                    h = u.get("hook")
                    if h and h[0] == "mod":
                        out[(h[1], h[2])] = out.get((h[1], h[2]), 0) + u["max"]
    return out


_t7_apply()


def check():
    """the table's own rules (every build script that imports it calls this)"""
    names = [t["name"] for t in TREES]
    assert len(TREES) == 19 and len(set(names)) == 19
    assert sum(1 for t in TREES if t["kind"] == "class") == 8 and sum(1 for t in TREES if t["kind"] == "skill") == 11
    for t in TREES:
        if t.get("v4"):   # 0.6.0: a rebuilt class tree has its own rules (v4_check below)
            continue
        nb, nr = (2, 4) if t["light"] else (3, 6)
        assert (t["name"] in LIGHT) == t["light"] and len(t["branches"]) == nb, t["name"]
        for b in t["branches"]:
            assert len(b["rows"]) == nr and [r["r"] for r in b["rows"]] == list(range(1, nr + 1)), (t["name"], b["name"])
            ids = set()
            for r in b["rows"]:
                assert r["gate"] == GATE_STEP * (r["r"] - 1) and r["cap"] == (r["r"] == nr), (t["name"], r["r"])
                assert 1 <= len(r["ups"]) <= 3 and (not r["cap"] or (len(r["ups"]) == 1 and r["ups"][0]["max"] == 1 and r["ups"][0]["cost"] == CAP_COST))
                for u in r["ups"]:
                    assert u["id"] not in ids and 1 <= u["max"] <= 5 and u["cost"] == (CAP_COST if r["cap"] else RANK_COST), (t["name"], u)
                    ids.add(u["id"])
                    h = u["hook"]
                    assert h is None or (h[0] in ("mod", "fx") and t["kind"] == "class") or (h[0] == "old" and t["kind"] == "skill"), u
                    assert t["kind"] != "class" or h is not None, ("R3a: every class upgrade is wired", t["name"], u["name"])
                    for c, v in fx_codes(u):   # R3a: every code is known, has an owner, and a positive per-rank value
                        assert v > 0 and (c in FX_OWNER or c in FX_CLASSES or (c.startswith("a.") and c.split(".")[-1] in FX_AP and c.count(".") == 2)), (u["name"], c)
                    assert ("now" in u) == bool(fx_codes(u)), u["name"]
                f = r["free"]
                assert f is None or f["hook"] is None or (f["hook"][0] in ("abil", "fx") and t["kind"] == "class") or (f["hook"][0] == "old" and t["kind"] == "skill")
        if t["kind"] == "class":
            frees = [r["free"]["hook"] for b in t["branches"] for r in b["rows"] if r["free"] and r["free"]["hook"] and r["free"]["hook"][0] == "abil"]
            assert len(set(h[1] for h in frees)) == len(frees) and t["branches"][0]["rows"][0]["free"]["hook"][1] == "A1", t["name"]
    # R3a: a code whose rank count matters has ONE per-rank value; every listed SkyyClasses code is used; ASCII texts
    per = {}
    used = set()
    for t in TREES:
        for b in t["branches"]:
            for r in b["rows"]:
                if r["free"] and r["free"]["hook"] and r["free"]["hook"][0] == "fx":
                    used.add(r["free"]["hook"][1])
                for u in r["ups"]:
                    assert all(ord(ch) < 128 for ch in u["name"] + u["text"] + u.get("now", "")), u["name"]
                    for c, v in fx_codes(u):
                        used.add(c)
                        rk = c if c in FX_RANKED else ("a.*." + c.split(".")[-1] if c.startswith("a.") and "a.*." + c.split(".")[-1] in FX_RANKED else None)
                        if rk:
                            assert per.setdefault(c, v) == v, ("one per-rank value for a ranked code", c)
    assert not [c for c in FX_CLASSES if c not in used], [c for c in FX_CLASSES if c not in used]
    assert not [c for c in FX_OWNER if c not in used], [c for c in FX_OWNER if c not in used]
    _mr = mod_ranks()   # Balance P4 T7: no (ability, modifier) over MOD_CAP ranks in the class trees
    assert all(v <= MOD_CAP for v in _mr.values()), sorted((k, v) for k, v in _mr.items() if v > MOD_CAP)
    if globals().get("V4_APPLIED"):   # 0.6.0: the rebuilt class trees (defined at the end of this file)
        v4_check()
    return True


check()

# ===================================================================================================================================
# Balance P8b (research/Balance-P8-Rebirth-Spec.md 4.2; SkyyTrees 0.4.6 + SkyyClasses 0.1.45 + SkyyMobs 0.1.15, 2026-10-22): the essential
# skill trees Mining, Foraging, Combat row by row. Skyy (2026-10-20/21): "keep going down the list. dont stop until the entire list is done" +
# "just go with the recommended on all of them" (spec Q5 [yes]: an upgrade that cannot work as drafted gets the nearest working effect with
# honest text). Three upgrades become aliases of a 0.3 node (P8B_OLD; their sum stays inside the node's max - asserted by SkyyTrees); every
# other wired upgrade keeps hook None and is applied through tools/trees_v3_effects.py EFFECTS (SkyyTrees' own rows, SkyyClasses, SkyyMobs).
# P8B_TEXT = the honest page texts ("<Tree>.b<n>.<id>"; a row's free perk "<Tree>.b<n>.r<row>.free"). Two live texts said more than the
# node gives (Gem Eye 3 MGems levels x 0.02 % = +0.06 % a rank, not +2 %; Wide Burst 1 Vein Burst level = +1 ore a rank, not +2) - fixed.
P8B_OLD = {"Mining.b1.r2c": (("old", "Mining.MWisdom", 2), "+2% Mining XP/rank"),
           "Mining.b1.r3c": (("old", "Mining.MSpeed", 1), "+1.6% pickaxe swing speed/rank (1 Mining Speed level)"),
           "Foraging.b1.r3b": (("old", "Foraging.FSpeed", 1), "+1% chopping speed/rank")}
P8B_TEXT = {
    # Mining (Vein Burst is passive with no cooldown since SkyyTrees 0.3.24: the cooldown row gives vein size instead)
    "Mining.b1.r2b": "Burst Reach: Vein Burst breaks 1 more ore/rank (it has no cooldown)",
    "Mining.b2.r2.free": "-10% fall damage",
    "Mining.b2.r2a": "+2% max Health/rank",
    "Mining.b2.r2b": "+2% move speed/rank",
    "Mining.b2.r4b": "+1.5% damage/rank",
    "Mining.b2.r5c": "Vein Burst breaks 2 more ore/rank",
    "Mining.b3.r3b": "2% chance/rank an ore also pays coins (your Mining level)",
    "Mining.b3.r4a": "+0.06% chance/rank per block for a random gem (adds to Gem Eye)",
    "Mining.b3.r5b": "+2% move speed/rank",
    "Mining.b1.r3a": "+0.06% chance per block for a random gem/rank",
    "Mining.b1.r2a": "+1 vein size/rank",
    # Foraging
    "Foraging.b1.r2b": "Timber reach: Tree Feller breaks 1 more log/rank",
    "Foraging.b1.r4a": "+0.8% chance/rank a log drops once more",
    "Foraging.b1.r5b": "+1.5% Foraging XP/rank",
    "Foraging.b3.r1a": "+2% move speed/rank",
    "Foraging.b3.r3b": "+2% max Health/rank",
    "Foraging.b3.r3c": "-5% fall damage/rank",
    # Combat (points = the class level; the fight rows go through SkyyClasses inside its tree caps, the loot rows through SkyyMobs)
    "Combat.b1.r1.free": "+3% damage",
    "Combat.b1.r3a": "+4% damage/rank to enemies below 30% Health",
    "Combat.b1.r3b": "+1% move speed/rank",
    "Combat.b1.r5a": "+3% damage/rank to bosses and mini bosses",
    "Combat.b2.r1a": "+0.5% max Health/rank",
    "Combat.b2.r1b": "+3% knockback resistance/rank",
    "Combat.b2.r3a": "+2% damage reduction/rank",
    "Combat.b3.r1a": "+2% chance/rank a kill drops 1 more item of its loot (never gear)",
    "Combat.b3.r1b": "3% chance/rank a kill also pays coins (the mob's level)",
    "Combat.b3.r3b": "+1% chance/rank a kill drops 1 more of its rarest loot (never gear)",
    "Combat.b3.r4a": "+3% chance/rank a boss or mini boss drops its loot once more (never gear)",
    "Combat.b3.r5a": "2% chance/rank a kill drops its whole loot twice (never gear)",
}
P8B_TEXT_OLD = {"Mining.b1.r3a": "+2% gem drop chance/rank", "Mining.b1.r2a": "+2 vein size/rank"}   # the two live texts fixed (asserted)


def _p8b_apply():
    seen = set()
    for t in TREES:
        if t["name"] not in ("Mining", "Foraging", "Combat"):
            continue
        for bn, b in enumerate(t["branches"]):
            for r in b["rows"]:
                fk = "%s.b%d.r%d.free" % (t["name"], bn + 1, r["r"])
                if fk in P8B_TEXT:
                    assert r["free"] is not None and r["free"]["hook"] is None, fk
                    r["free"]["text"] = P8B_TEXT[fk]
                    seen.add(fk)
                for u in r["ups"]:
                    k = "%s.b%d.%s" % (t["name"], bn + 1, u["id"])
                    if k in P8B_OLD:
                        assert u["hook"] is None, ("P8b wires only coming-soon upgrades", k)
                        u["hook"], u["text"] = P8B_OLD[k]
                        seen.add(k)
                    if k in P8B_TEXT:
                        assert (u["hook"] is None) != (k in P8B_TEXT_OLD), ("P8b texts: a wired coming-soon upgrade or a fixed live one", k)
                        assert k not in P8B_TEXT_OLD or u["text"] == P8B_TEXT_OLD[k], ("P8b: the live text moved", k, u["text"])
                        u["text"] = P8B_TEXT[k]
                        seen.add(k)
    assert seen == set(P8B_OLD) | set(P8B_TEXT), sorted(set(P8B_OLD) | set(P8B_TEXT) - seen)


_p8b_apply()
check()

# ===================================================================================================================================
# Balance P8c (research/Balance-P8-Rebirth-Spec.md 4.4; SkyySkills 0.4.60 + SkyyPets 0.4.9 + SkyyTrees 0.4.7, 2026-10-22): the Beastmastery
# tree. Skyy (2026-10-20/21): "keep going down the list. dont stop until the entire list is done" + "just go with the recommended on all of
# them" (spec Q5 [yes]: an upgrade that cannot work as drafted gets the nearest working effect with honest text; Q7 [yes]: the Beastmastery
# skill levels from the XP your pets gain and its points open this tree). The pet XP / pet stat rows are applied by SkyyPets through
# tools/trees_v3_effects.py EFFECTS (hook None, like P8b); the per-pet-kind budgets (pet XP <= 30 %, pet stats <= 15 % a kind) are proved by
# trees_v3_effects.check(). P8C_TEXT = the texts that change (the rest of the wired texts already say what the row does):
#   Whistle Training "+2 flat pet XP/rank" -> a % (flat pet XP is meaningless after Balance P3's per-tier XP; the Combat pet XP budget 30 % =
#     3 + 9 + 12 + 6), Digger's Calling / Green Companion +3 % -> +2.4 % a rank (5 x 2.4 + 12 + 6 = 30 %, the spec's per-kind pet XP budget),
#     Gentle Giant "+10% pet bonus from rare pets/rank" -> +1 % all stats of Rare or better pets a rank, and (fixer) the bottom capstone Kinship
#     of the Wild's "all equipped pets gain +10% all stats" -> +3 % all stats of every pet (docs/answered/skills.md 2026-10-16 BEASTMASTERY
#     GLOBAL NODE, Skyy: "actually, do add the +% global power at the bottom"; each kind's pet stats 4 + 6 + 2 + 3 = 15 %; the extra pet slot
#     stays coming soon).
# Coming soon (no system yet, named in the spec 4.4 / 4.1): Bond of Beasts (needs a pet-active kill counter), the actives Rally Cry / Pet Dig /
# Pet Harvest and their modifier rows, Pack Speed / Alpha's Mark / Pack Instinct / Guard Dog (summoned fighters attack with the game's own NPC
# attacks - SkyyPets has no pet damage numbers yet), Cave Nose (ore detection), Ore Sniffer / Fertile Trail / Gem Hound / Burrow Rush (the
# Mining / Foraging / Farming Fortune and speed budgets are their own trees'), Pet Picnic (no feeding system),
# Glimmering Coat (visual), the capstones Apex Bond / Heart of Stone (Rally Cry / Pet Dig) and Kinship's extra pet slot.
P8C_TEXT = {"Beastmastery.b1.r1a": "+0.6% Combat pet XP/rank",
            "Beastmastery.b2.r1a": "+2.4% Mining pet XP/rank",
            "Beastmastery.b3.r1a": "+2.4% Farming/Foraging pet XP/rank",
            "Beastmastery.b3.r5b": "+1% all stats from Rare or better pets/rank",
            "Beastmastery.b3.r1b": "+1 Hatchery slot/rank",   # fixer 2: docs/answered/pets.md 2026-10-16 LOCKED "the hatchery has limited slots (upgradable in beast masters skill tree" (no happiness system)
            "Beastmastery.b3.r6": "+3% all stats from every pet you equip (the extra pet slot: coming soon)"}
P8C_TEXT_OLD = {"Beastmastery.b1.r1a": "+2 flat pet XP/rank", "Beastmastery.b2.r1a": "+3% Mining pet XP/rank",
                "Beastmastery.b3.r1a": "+3% Farming/Foraging pet XP/rank", "Beastmastery.b3.r5b": "+10% pet bonus from rare pets/rank",
                "Beastmastery.b3.r1b": "+3% pet happiness/rank",
                "Beastmastery.b3.r6": "equip one extra pet slot; all equipped pets gain +10% all stats (+20% for Farming and Foraging)."}


def _p8c_apply():
    t = tree("Beastmastery")
    seen = set()
    for bn, b in enumerate(t["branches"]):
        for r in b["rows"]:
            for u in r["ups"]:
                k = "Beastmastery.b%d.%s" % (bn + 1, u["id"])
                if k in P8C_TEXT:
                    assert u["hook"] is None and u["text"] == P8C_TEXT_OLD[k], ("P8c: the text moved", k, u["text"])
                    u["text"] = P8C_TEXT[k]
                    seen.add(k)
    assert seen == set(P8C_TEXT), sorted(set(P8C_TEXT) - seen)


_p8c_apply()
check()

# ===================================================================================================================================
# Balance P8d (research/Balance-P8-Rebirth-Spec.md 4.5; SkyyTrees 0.4.8, 2026-10-22): the useful trees Farming / Cooking / Alchemy and the
# light trees Fishing / Smithing / Acrobatics / Exploration row by row. Skyy (2026-10-20/21): "keep going down the list. dont stop until the
# entire list is done" + "just go with the recommended on all of them" (spec Q4 [yes]: actives stay coming soon; Q5 [yes]: an upgrade that
# cannot work as drafted gets the nearest working effect with honest text). No applier mod is rebuilt: every new effect is a 0.3 node alias
# (P8D_OLD, read by the mods that already read that node: SkyyTrees itself for Farming, SkyyCooking for the Grade nodes, SkyyFishing for Quick
# Bite / Fishing Fortune) or one of SkyyTrees' own TreeSk rows (tools/trees_v3_effects.py EFFECTS, applier "SkyyTrees").
# P8D_DROP (builder finding, 2026-10-22): 9 upgrades aliased a 0.3 node that NO mod in the SET reads any more (SkyySkills 0.4.60 has no brew
# code - Alchemy.PDur / PDouble / PFrugal / PMaster; SkyyGear 0.3.36 / SkyySacks 0.8.27 never read Smithing.SQuick / SReforge / SRarity;
# SkyyFishing 0.1.12 reads only NBite / NFortune / NTreasure - not NRare / NLine). They were never buyable ("Coming with <mod>") but their
# ranks counted in the row gates, so Alchemy rows 2-6, Smithing rows 2-4 and Fishing row 3 could never open. They lose the dead hook (coming
# soon, honestly) - Steady Strikes is rewired to Smithing XP (EFFECTS) - and the gates fall to what is really buyable. Nobody owns a rank in
# them (never buyable; the live NewBetaTest files hold no rank in these seven trees).
P8D_OLD = {"Farming.b1.r3b": (("old", "Farming.ASeeds", 4), "+4% chance per crop for 1 of its seeds (no auto-replant yet)"),
           "Farming.b3.r3a": (("old", "Farming.ASeeds", 1), "+1% chance/rank per crop for 1 of its seeds"),
           "Cooking.b1.r1b": (("old", "Cooking.CGourmet", 2), "+1.6% chance/rank a dish comes out 1 Grade higher"),
           "Cooking.b1.r3b": (("old", "Cooking.CGourmet2", 2), "+2% chance/rank of +1 Grade on any dish"),
           "Cooking.b2.r1b": (("old", "Cooking.CGourmet", 1), "+0.8% chance/rank a dish comes out 1 Grade higher"),
           "Cooking.b3.r5a": (("old", "Cooking.CSig", 1), "+1% chance/rank of +2 Grades on a dish"),
           "Alchemy.b2.r1a": (("old", "Farming.AHerbs", 2), "+3% extra-drop chance/rank on health, mana and stamina crops"),
           "Alchemy.b2.r2a": (("old", "Farming.AHerbs", 2), "+3% extra-drop chance/rank on health, mana and stamina crops"),
           "Fishing.b1.r3a": (("old", "Fishing.NBite", 2), "+2% bite speed/rank"),
           "Fishing.b2.r3b": (("old", "Fishing.NFortune", 2), "+2% double-catch chance/rank")}
P8D_DROP = {"Alchemy.b1.r1b": "Alchemy.PDur", "Alchemy.b1.r3a": "Alchemy.PDouble", "Alchemy.b1.r3b": "Alchemy.PFrugal", "Alchemy.b1.r4a": "Alchemy.PMaster",
            "Smithing.b1.r1a": "Smithing.SQuick", "Smithing.b1.r2b": "Smithing.SReforge", "Smithing.b1.r3c": "Smithing.SRarity",
            "Fishing.b1.r2a": "Fishing.NRare", "Fishing.b2.r2b": "Fishing.NLine"}
# the texts of the rows SkyyTrees' own TreeSk applies (trees_v3_effects.py EFFECTS) + two live texts that said more than the node gives
P8D_TEXT = {"Farming.b1.r1b": "+1% move speed/rank (crops already break in one hit)",
            "Farming.b1.r4b": "+0.9 Farming Fortune/rank (on every harvest)",
            "Cooking.b1.r4a": "+1% max Health/rank (always on - no meal timer yet)",
            "Alchemy.b3.r1a": "+1% max Health/rank",
            "Smithing.b1.r1a": "+2% Smithing XP/rank (craft speed is fixed by the game)",
            "Acrobatics.b1.r3b": "+2% dodge push/rank (Hytale has no dodge chance)",
            "Acrobatics.b1.r3c": "+1% move speed/rank",
            "Acrobatics.b2.r1a": "+1% move speed/rank (at any Health)",
            "Acrobatics.b2.r2b": "-2% fall damage/rank",
            "Acrobatics.b2.r3b": "+2% dodge push/rank",
            "Acrobatics.b2.r3c": "-3% fall damage/rank (at any Health)",
            "Exploration.b1.r1b": "+0.3 max Stamina/rank (3% of the base 10)",
            "Exploration.b2.r2b": "-5% fall damage/rank",
            # live texts fixed (asserted against P8D_TEXT_OLD): Light Feet = 2 Soft Landing levels (-1 % each) a rank; Chain Jump = 5 Double
            # Jump levels a rank (base 50 % + 5 % a level of your jump height: 75 % at rank 1, 100 % at rank 2 - one mid-air jump, never two)
            "Acrobatics.b1.r3a": "-2% fall damage/rank",
            "Acrobatics.b1.r2b": "one mid-air jump at 75% of your jump height (100% at rank 2)"}
P8D_TEXT_OLD = {"Acrobatics.b1.r3a": "-5% fall damage/rank", "Acrobatics.b1.r2b": "+1 midair jump per 2 ranks"}
P8D_TREES = ("Farming", "Cooking", "Alchemy", "Fishing", "Smithing", "Acrobatics", "Exploration")


def _p8d_apply():
    seen = set()
    for t in TREES:
        if t["name"] not in P8D_TREES:
            continue
        for bn, b in enumerate(t["branches"]):
            for r in b["rows"]:
                for u in r["ups"]:
                    k = "%s.b%d.%s" % (t["name"], bn + 1, u["id"])
                    if k in P8D_DROP:
                        assert u["hook"] is not None and u["hook"][0] == "old" and u["hook"][1] == P8D_DROP[k], ("P8d: the dead alias moved", k, u["hook"])
                        u["hook"] = None
                        seen.add(k)
                    if k in P8D_OLD:
                        assert u["hook"] is None, ("P8d wires only coming-soon upgrades", k)
                        u["hook"], u["text"] = P8D_OLD[k]
                        seen.add(k)
                    if k in P8D_TEXT:
                        assert (u["hook"] is None) != (k in P8D_TEXT_OLD), ("P8d texts: a wired coming-soon upgrade or a fixed live one", k)
                        assert k not in P8D_TEXT_OLD or u["text"] == P8D_TEXT_OLD[k], ("P8d: the live text moved", k, u["text"])
                        u["text"] = P8D_TEXT[k]
                        seen.add(k)
    assert seen == set(P8D_OLD) | set(P8D_DROP) | set(P8D_TEXT), sorted(set(P8D_OLD) | set(P8D_DROP) | set(P8D_TEXT) - seen)
    assert not set(P8D_OLD) & set(P8D_DROP)


_p8d_apply()
check()


# ---------------------------------------------------------------------------------------------------- BALANCE P7b (2026-10-22, SkyyTrees 0.4.9 +
# SkyyExploration 0.3.3). Skyy 2026-10-22 popup "Two Exploration tree upgrades (Wanderer, Cartographer) were designed to boost Exploration XP, but
# your earlier rule says Exploration XP never gets boosts or tree bonuses. Which wins?" -> "Keep the no-boost rule (Recommended)" -> both get a
# non-XP effect (docs/answered/skills.md 2026-10-22 EXPLORATION TREE): SkyyExploration applies them (trees_v3_effects.py EFFECTS, applier
# SkyyExploration) on Loot Bag + supply drop COINS only - never Exploration XP, never more bags (more bags would mean more Exploration XP).
P7B_TEXT = {"Exploration.b1.r1a": "+4% coins/rank from Loot Bags and supply drops",
            "Exploration.b1.r3a": "+5% chance/rank a Loot Bag or supply drop holds a second coin find"}
P7B_TEXT_OLD = {"Exploration.b1.r1a": "+2% exploration XP/rank", "Exploration.b1.r3a": "+3% map-discovery XP/rank"}


def _p7b_apply():
    seen = set()
    t = tree("Exploration")
    for bn, b in enumerate(t["branches"]):
        for r in b["rows"]:
            for u in r["ups"]:
                k = "%s.b%d.%s" % (t["name"], bn + 1, u["id"])
                if k in P7B_TEXT:
                    assert u["hook"] is None and u["text"] == P7B_TEXT_OLD[k], ("P7b: Wanderer / Cartographer moved", k, u)
                    u["text"] = P7B_TEXT[k]
                    seen.add(k)
    assert seen == set(P7B_TEXT), sorted(set(P7B_TEXT) - seen)
    assert [u["name"] for b in t["branches"] for r in b["rows"] for u in r["ups"] if "Exploration.b%d.%s" % (t["branches"].index(b) + 1, u["id"]) in P7B_TEXT] == ["Wanderer", "Cartographer"]


_p7b_apply()
check()


